class Solution {
  public List<List<Integer>> findDisappearedNumbers(int[] nums, int lower, int upper) {
    boolean[] present = new boolean[upper + 2];
    for (int v : nums) if (v >= lower && v <= upper) present[v] = true;
    List<List<Integer>> res = new ArrayList<>();
    int i = lower;
    while (i <= upper) {
      if (present[i]) {
        i++;
        continue;
      }
      int j = i;
      while (j + 1 <= upper && !present[j + 1]) j++;
      res.add(java.util.Arrays.asList(i, j));
      i = j + 1;
    }
    return res;
  }
}
